B=[
('الرِّحْلَةُ الْخَامِسَةُ: الْبَيْضَةُ الْبَيْضَاءُ','Beşinci yolculuk: Beyaz yumurta',[
('فِي الْيَوْمِ التَّالِي جَاءَ الْحَمَّالُ، فَجَلَسَ مَعَ الْأَصْحَابِ.','Ertesi gün hamal geldi ve arkadaşlarla birlikte oturdu.'),
('قَالَ السِّنْدِبَادُ: «نَسِيتُ تَعَبِي، وَاشْتَرَيْتُ سَفِينَةً جَدِيدَةً لِي وَحْدِي.»','Sindbad dedi ki: “Yorgunluğumu unuttum ve kendime ait yeni bir gemi satın aldım.”'),
('«وَجَمَعْتُ فِيهَا تُجَّارًا كَثِيرِينَ، وَخَرَجْنَا مِنَ الْبَصْرَةِ.»','“İçine birçok tüccar topladım ve Basra’dan çıktık.”'),
('«وَبَعْدَ أَيَّامٍ وَصَلْنَا إِلَى جَزِيرَةٍ خَالِيَةٍ.»','“Günler sonra boş bir adaya vardık.”'),
('«فَرَأَيْنَا عَلَى الرَّمْلِ قُبَّةً بَيْضَاءَ كَبِيرَةً.»','“Kumun üzerinde büyük, beyaz bir kubbe gördük.”'),
('«عَرَفْتُ أَنَّهَا بَيْضَةُ الرُّخِّ، فَقُلْتُ لَهُمْ: لَا تَقْرَبُوهَا!»','“Onun Rûh kuşunun yumurtası olduğunu anladım ve onlara dedim ki: Ona yaklaşmayın!”'),
('«لَكِنَّهُمْ لَمْ يَسْمَعُوا كَلَامِي، فَضَرَبُوهَا بِالْحِجَارَةِ.»','“Ama sözümü dinlemediler ve ona taşlarla vurdular.”'),
('«فَانْكَسَرَتِ الْبَيْضَةُ، وَخَرَجَ مِنْهَا فَرْخٌ صَغِيرٌ، فَذَبَحُوهُ وَأَكَلُوا لَحْمَهُ.»','“Yumurta kırıldı, içinden küçük bir yavru çıktı; onu kesip etini yediler.”')]),
('غَضَبُ الرُّخِّ','Rûh kuşunun öfkesi',[
('«فَجْأَةً أَظْلَمَتِ السَّمَاءُ، كَأَنَّ غَيْمَةً سَوْدَاءَ جَاءَتْ.»','“Birden gökyüzü karardı; sanki kara bir bulut gelmişti.”'),
('«فَنَظَرْنَا، فَإِذَا الرُّخُّ وَزَوْجَتُهُ يَطِيرَانِ فَوْقَنَا.»','“Baktık; bir de ne görelim, Rûh kuşu ve eşi üstümüzde uçuyor.”'),
('«صَاحَا صِيَاحًا شَدِيدًا لَمَّا رَأَيَا الْبَيْضَةَ مَكْسُورَةً.»','“Yumurtayı kırık görünce şiddetle bağırdılar.”'),
('«فَقُلْتُ: إِلَى السَّفِينَةِ بِسُرْعَةٍ!»','“Dedim ki: Çabuk gemiye!”'),
('«فَرَكِبْنَا وَرَفَعْنَا الشِّرَاعَ، وَهَرَبْنَا فِي الْبَحْرِ.»','“Bindik, yelkeni açtık ve denize kaçtık.”'),
('«لَكِنَّ الطَّائِرَيْنِ رَجَعَا، وَفِي أَرْجُلِهِمَا صُخُورٌ عَظِيمَةٌ.»','“Ama iki kuş geri döndü; ayaklarında koca kayalar vardı.”'),
('«فَرَمَى الْأَوَّلُ صَخْرَتَهُ، فَسَقَطَتْ قُرْبَ السَّفِينَةِ.»','“Birincisi kayasını attı; geminin yakınına düştü.”'),
('«ثُمَّ رَمَى الثَّانِي صَخْرَتَهُ، فَوَقَعَتْ عَلَى السَّفِينَةِ وَكَسَرَتْهَا.»','“Sonra ikincisi kayasını attı; geminin üstüne düştü ve onu kırdı.”')]),
('شَيْخُ الْبَحْرِ','Denizin ihtiyarı',[
('«غَرِقَ كُلُّ مَنْ فِي السَّفِينَةِ، وَنَجَوْتُ أَنَا عَلَى لَوْحٍ.»','“Gemide olan herkes boğuldu; ben bir tahta üzerinde kurtuldum.”'),
('«وَصَلْتُ إِلَى جَزِيرَةٍ جَمِيلَةٍ فِيهَا أَشْجَارٌ وَأَنْهَارٌ.»','“Ağaçları ve ırmakları olan güzel bir adaya vardım.”'),
('«أَكَلْتُ مِنَ الثِّمَارِ، وَشَرِبْتُ مِنَ الْمَاءِ، وَنِمْتُ.»','“Meyvelerden yedim, sudan içtim ve uyudum.”'),
('«وَفِي الصَّبَاحِ رَأَيْتُ شَيْخًا ضَعِيفًا جَالِسًا عِنْدَ النَّهْرِ.»','“Sabah ırmağın yanında oturan zayıf bir ihtiyar gördüm.”'),
('«أَشَارَ إِلَيَّ بِيَدِهِ: احْمِلْنِي إِلَى الْجِهَةِ الْأُخْرَى.»','“Eliyle bana işaret etti: Beni öbür tarafa taşı.”'),
('«قُلْتُ فِي نَفْسِي: هَذَا شَيْخٌ مِسْكِينٌ، وَالْخَيْرُ فِيهِ أَجْرٌ.»','“İçimden dedim ki: Bu zavallı bir ihtiyar; iyilikte sevap var.”'),
('«فَحَمَلْتُهُ عَلَى كَتِفَيَّ، وَعَبَرْتُ النَّهْرَ.»','“Onu omuzlarıma aldım ve ırmağı geçtim.”'),
('«فَلَمَّا وَصَلْنَا قُلْتُ: انْزِلْ يَا شَيْخُ. لَكِنَّهُ لَمْ يَنْزِلْ.»','“Varınca dedim ki: İn ey ihtiyar. Ama inmedi.”')]),
('الْحِمْلُ الثَّقِيلُ','Ağır yük',[
('«لَفَّ رِجْلَيْهِ حَوْلَ عُنُقِي بِقُوَّةٍ، حَتَّى كِدْتُ أَمُوتُ.»','“Bacaklarını boynuma kuvvetle doladı; neredeyse ölecektim.”'),
('«كَانَتْ رِجْلَاهُ قَوِيَّتَيْنِ مِثْلَ الْحِبَالِ.»','“Bacakları ip gibi güçlüydü.”'),
('«وَكَانَ يَضْرِبُنِي بِرِجْلِهِ، وَيُشِيرُ: امْشِ إِلَى هُنَاكَ.»','“Ayağıyla bana vuruyor ve işaret ediyordu: Oraya yürü.”'),
('«فَمَشَيْتُ بِهِ أَيَّامًا وَلَيَالِيَ، وَهُوَ لَا يَنْزِلُ أَبَدًا.»','“Onunla günlerce, gecelerce yürüdüm; o ise hiç inmiyordu.”'),
('«كَانَ يَأْكُلُ مِنَ الشَّجَرِ وَهُوَ عَلَى ظَهْرِي، وَيَنَامُ عَلَى ظَهْرِي.»','“Sırtımdayken ağaçtan yiyor, sırtımda uyuyordu.”'),
('«فَقُلْتُ: يَا لَيْتَنِي مَا حَمَلْتُهُ!»','“Dedim ki: Keşke onu hiç taşımasaydım!”'),
('«لَكِنِّي لَمْ أَيْأَسْ مِنْ رَحْمَةِ اللّٰهِ.»','“Ama Allah’ın rahmetinden ümit kesmedim.”')]),
('الْحِيلَةُ','Hile',[
('«وَجَدْتُ يَقْطِينًا كَبِيرًا يَابِسًا تَحْتَ شَجَرَةٍ.»','“Bir ağacın altında büyük, kuru bir su kabağı buldum.”'),
('«فَتَحْتُهُ وَنَظَّفْتُهُ، وَعَصَرْتُ فِيهِ عِنَبًا كَثِيرًا.»','“Onu açtım, temizledim ve içine çok üzüm sıktım.”'),
('«وَتَرَكْتُهُ فِي الشَّمْسِ أَيَّامًا، فَصَارَ شَرَابًا قَوِيًّا.»','“Onu günlerce güneşte bıraktım; sert bir içki oldu.”'),
('«رَآنِي الشَّيْخُ أَحْمِلُ الْيَقْطِينَ، فَأَشَارَ: أَعْطِنِي.»','“İhtiyar kabağı taşıdığımı gördü ve işaret etti: Bana ver.”'),
('«فَأَعْطَيْتُهُ، فَشَرِبَ كُلَّ مَا فِيهِ.»','“Ona verdim; içindekinin hepsini içti.”'),
('«فَسَكِرَ، وَضَعُفَتْ رِجْلَاهُ، وَأَخَذَ يَتَمَايَلُ.»','“Sarhoş oldu, bacakları gevşedi ve sallanmaya başladı.”'),
('«فَرَمَيْتُهُ عَنْ ظَهْرِي إِلَى الْأَرْضِ، وَهَرَبْتُ مِنْهُ.»','“Onu sırtımdan yere attım ve ondan kaçtım.”'),
('«وَشَكَرْتُ اللّٰهَ عَلَى الْخَلَاصِ.»','“Kurtuluş için Allah’a şükrettim.”')]),
('مَدِينَةُ جَوْزِ الْهِنْدِ','Hindistan cevizi şehri',[
('«بَعْدَ أَيَّامٍ مَرَّتْ سَفِينَةٌ، فَحَمَلَنِي أَهْلُهَا.»','“Günler sonra bir gemi geçti; içindekiler beni aldı.”'),
('«قَالُوا: نَجَوْتَ مِنْ شَيْخِ الْبَحْرِ! لَمْ يَنْجُ مِنْهُ أَحَدٌ قَبْلَكَ.»','“Dediler ki: Denizin ihtiyarından kurtuldun! Senden önce kimse ondan kurtulmadı.”'),
('«وَصَلْنَا إِلَى مَدِينَةٍ بُيُوتُهَا عَالِيَةٌ قُرْبَ الْجَبَلِ.»','“Evleri yüksek olan, dağa yakın bir şehre vardık.”'),
('«أَعْطَانِي رَجُلٌ كِيسًا، وَقَالَ: امْلَأْهُ حِجَارَةً، وَاخْرُجْ مَعَ النَّاسِ.»','“Bir adam bana bir torba verdi ve dedi ki: Onu taşla doldur ve insanlarla birlikte çık.”'),
('«خَرَجْنَا إِلَى غَابَةٍ فِيهَا أَشْجَارُ جَوْزِ الْهِنْدِ عَالِيَةٌ جِدًّا.»','“İçinde çok yüksek hindistan cevizi ağaçları olan bir ormana çıktık.”'),
('«وَعَلَى الْأَشْجَارِ قُرُودٌ كَثِيرَةٌ.»','“Ağaçların üstünde birçok maymun vardı.”'),
('«رَمَيْنَا الْقُرُودَ بِالْحِجَارَةِ، فَغَضِبَتْ وَرَمَتْنَا بِجَوْزِ الْهِنْدِ!»','“Maymunlara taş attık; kızdılar ve bize hindistan cevizi attılar!”'),
('«فَجَمَعْنَا الْجَوْزَ، وَبِعْنَاهُ فِي السُّوقِ بِمَالٍ كَثِيرٍ.»','“Cevizleri topladık ve çarşıda çok paraya sattık.”')]),
('اللُّؤْلُؤُ وَالْعَوْدَةُ','İnciler ve dönüş',[
('«فَعَلْتُ ذَلِكَ أَيَّامًا كَثِيرَةً، حَتَّى جَمَعْتُ مَالًا.»','“Bunu uzun günler yaptım; sonunda para biriktirdim.”'),
('«ثُمَّ رَكِبْتُ سَفِينَةً إِلَى جَزَائِرِ اللُّؤْلُؤِ.»','“Sonra inci adalarına giden bir gemiye bindim.”'),
('«أَعْطَيْتُ الْغَوَّاصِينَ مَالًا، فَغَاصُوا لِي فِي الْبَحْرِ.»','“Dalgıçlara para verdim; benim için denize daldılar.”'),
('«فَأَخْرَجُوا لُؤْلُؤًا كَبِيرًا جَمِيلًا.»','“Büyük ve güzel inciler çıkardılar.”'),
('«وَرَجَعْتُ إِلَى بَغْدَادَ بِاللُّؤْلُؤِ وَالْجَوْزِ وَالْعُودِ.»','“İnciler, cevizler ve öd ağacıyla Bağdat’a döndüm.”'),
('«وَتَصَدَّقْتُ عَلَى الْفُقَرَاءِ كَمَا فَعَلْتُ مِنْ قَبْلُ.»','“Daha önce yaptığım gibi fakirlere sadaka verdim.”'),
('قَالَ الْحَمَّالُ: «تَعَلَّمْتُ الْيَوْمَ أَنَّ الْخَيْرَ لَا يَكُونُ لِكُلِّ أَحَدٍ.»','Hamal dedi ki: “Bugün öğrendim ki iyilik herkese yapılmaz.”'),
('قَالَ السِّنْدِبَادُ: «بَلِ افْعَلِ الْخَيْرَ، وَلَكِنْ كُنْ عَاقِلًا. وَغَدًا الرِّحْلَةُ السَّادِسَةُ.»','Sindbad dedi ki: “Hayır, iyilik yap ama akıllı ol. Yarın da altıncı yolculuk.”')]),
]
